import { Group, Mesh, PlaneGeometry, Color, Vector3 } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group: CGroup } = ctx.THREE; // fallback if needed
  const root = new Group();

  // -----------------
  // Geometry & Materials
  // -----------------
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const BORDER_THICK = 0.006;
  const PADDING = 0.5;
  const HEADER_H = 0.08;
  const CTA_W = 1.4;
  const CTA_H = 0.36;
  const HAIRLINE_COLOR = '#23232b';
  const BORDER_COLOR = '#2a2a33';
  const SURFACE_COLOR = '#16161d';
  const PAPER_COLOR = '#e8ecf2';
  const ACCENT_EMISSIVE = '#ff2a38';

  // Outer border plane
  const borderGeom = new PlaneGeometry(CARD_W + BORDER_THICK * 2, CARD_H + BORDER_THICK * 2);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.color = new Color(BORDER_COLOR);
  const borderMesh = new Mesh(borderGeom, borderMat);
  borderMesh.position.z = -0.002;
  root.add(borderMesh);

  // Main card background
  const bgGeom = new PlaneGeometry(CARD_W, CARD_H);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.color = new Color(SURFACE_COLOR);
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -0.001;
  root.add(bgMesh);

  // Header strip (machined metal)
  const headerGeom = new PlaneGeometry(CARD_W, HEADER_H);
  const headerMat = new MeshStandardNodeMaterial();
  headerMat.color = new Color(SURFACE_COLOR);
  headerMat.metalness = 0.5;
  headerMat.roughness = 0.55;
  headerMat.clearcoat = 0.2;
  const headerMesh = new Mesh(headerGeom, headerMat);
  headerMesh.position.y = CARD_H / 2 - HEADER_H / 2;
  headerMesh.position.z = 0;
  root.add(headerMesh);

  // -----------------
  // Text creation helper
  // -----------------
  const textColor = new Color(PAPER_COLOR);
  function addText(content, opts, pos) {
    const txt = ctx.fontAtlas.createText(content, {
      fontSize: opts.fontSize,
      color: opts.color ?? textColor,
      align: opts.align ?? 'left',
      letterSpacingPx: opts.letterSpacing,
      maxWidthPx: opts.maxWidthPx,
    });
    txt.position.set(pos.x, pos.y, 0.001);
    root.add(txt);
    return txt;
  }

  // -----------------
  // Populate Text
  // -----------------
  const startY = CARD_H / 2 - PADDING; // top inner edge
  let curY = startY;

  // Tier name
  curY -= 0.2; // offset a bit from top edge
  const tierName = addText('ATELIER RESERVE', {
    fontSize: 20,
    letterSpacing: 0.08,
    lineHeight: 1.2,
    color: PAPER_COLOR,
  }, new Vector3(-CARD_W / 2 + PADDING, curY, 0));

  // Price
  curY -= 0.4;
  const price = addText('$480', {
    fontSize: 62,
    letterSpacing: -0.01,
    lineHeight: 1,
    color: PAPER_COLOR,
  }, new Vector3(-CARD_W / 2 + PADDING, curY, 0));

  // Caption
  curY -= 0.15;
  const caption = addText('PER MONTH, BILLED ANNUALLY', {
    fontSize: 9,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: PAPER_COLOR,
  }, new Vector3(-CARD_W / 2 + PADDING, curY, 0));

  // Gap before features
  curY -= 0.5;

  const featureTexts = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];
  const featureObjs = [];

  featureTexts.forEach((txt, idx) => {
    // Hairline separator (except before first)
    if (idx > 0) {
      const lineGeom = new PlaneGeometry(CARD_W - PADDING * 2, BORDER_THICK);
      const lineMat = new MeshBasicNodeMaterial();
      lineMat.color = new Color(HAIRLINE_COLOR);
      const lineMesh = new Mesh(lineGeom, lineMat);
      lineMesh.position.y = curY + 0.1875; // middle of the row
      lineMesh.position.z = 0;
      root.add(lineMesh);
    }

    const featureY = curY - idx * 0.375 - 0.1875; // center of the row
    const featureObj = addText(txt, {
      fontSize: 13,
      letterSpacing: 0,
      lineHeight: 1.5,
      color: PAPER_COLOR,
    }, new Vector3(-CARD_W / 2 + PADDING, featureY, 0));
    featureObjs.push(featureObj);
  });

  // CTA Row (gradient plane)
  const ctaGeom = new PlaneGeometry(CTA_W, CTA_H);
  const ctaMat = new MeshBasicNodeMaterial();
  // Gradient color node
  ctaMat.colorNode = mix(vec3('#ff4450'), vec3('#c1121f'), uv().y);
  ctaMat.emissiveNode = vec3(ACCENT_EMISSIVE);
  ctaMat.emissiveIntensity = 1.5;
  const ctaMesh = new Mesh(ctaGeom, ctaMat);
  ctaMesh.position.y = -CARD_H / 2 + PADDING + CTA_H / 2;
  ctaMesh.position.z = 0.001;
  root.add(ctaMesh);

  // CTA Label (centered)
  const ctaLabel = addText('JOIN THE RESERVE', {
    fontSize: 13,
    letterSpacing: 0.08,
    lineHeight: 1,
    color: PAPER_COLOR,
  }, new Vector3(0, ctaMesh.position.y, 0));

  // -----------------
  // Animation Timelines
  // -----------------
  const masterTL = gsap.timeline({ paused: true });

  // Mount settle animation
  root.scale.set(1.04, 1.04, 1.04);
  masterTL.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  }, 0);

  // Feature rows staggered fade-up
  featureObjs.forEach((obj, i) => {
    if (obj.material) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
    obj.position.y += 0.2;
    masterTL.to(obj.material, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, i * 0.08);
    masterTL.to(obj.position, {
      y: obj.position.y - 0.2,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, i * 0.08);
  });

  // Play immediately
  masterTL.play();

  // -----------------
  // Interaction Handlers (none defined, but placeholder)
  // -----------------
  const handlers = {};

  // -----------------
  // Cleanup
  // -----------------
  function cleanup() {
    masterTL.kill();
    // dispose geometries and materials
    [borderMesh, bgMesh, headerMesh, ctaMesh].forEach(m => {
      m.geometry.dispose();
      m.material.dispose();
    });
    featureObjs.concat([tierName, price, caption, ctaLabel]).forEach(o => {
      if (o && o.geometry) o.geometry.dispose();
      if (o && o.material) o.material.dispose();
    });
  }

  root.userData = { handlers, cleanup };
  return root;
}
